def test_top_customers_sorted_filtered_and_limited(shop):
    shop.customers.handle_register({"customer_id": "c0", "name": "Alan", "email": "a@example.com"})
    shop.customers.handle_register({"customer_id": "c3", "name": "Zed", "email": "z@example.com"})
    place(shop, "c1", ("BOOK", 1))        # 2500
    place(shop, "c2", ("BOOK", 1))        # 2500 (tie with c1)
    place(shop, "c0", ("LAMP", 2))        # 10800
    cancelled = place(shop, "c3", ("PEN", 1)).body["order_id"]
    shop.orders.handle_cancel(cancelled)  # c3 has value 0
    body = shop.insights.handle_top_customers(10).body
    assert body == {"customers": [
        {"customer_id": "c0", "name": "Alan", "lifetime_value_cents": 10800},
        {"customer_id": "c1", "name": "Ada", "lifetime_value_cents": 2500},
        {"customer_id": "c2", "name": "Grace", "lifetime_value_cents": 2500},
    ]}
    assert shop.insights.handle_top_customers(2).body["customers"] == body["customers"][:2]
    assert body["customers"][0]["lifetime_value_cents"] == \
        shop.insights.handle_lifetime_value("c0").body["lifetime_value_cents"]


